// Block (composition) — a sheet of options the reader picks ONE of, the way a list is sorted
// ("Lowest price", "Most data"): a bottom sheet below the `large` breakpoint and a centred panel at
// and above it. Pressing a row picks it and closes the sheet at once. The rows read as one grouped
// list, never loose rows on the sheet: one bordered box, each row a full control height, parted by
// hairlines (ListBox's `variant="grouped"`, always, since that is what the variant is for). Every row
// is plain text; the picked one takes the brand ink, the emphasized weight and a trailing check
// (ListBox's `indicator="check"`).
//
// The options may come in labelled groups, as a sheet that sorts two kinds of item at once does
// ("상품 정렬" and "구독 정렬"). Each group is then its own list with its own pick, so the value is a
// record keyed by group id, and each group is its own grouped box under its name. Such a sheet may end in an apply action (`onApply`): a pick then leaves
// the sheet open, and the reader confirms the picks of every group with one press.
//
// A sibling of ActionSheet, not a mode on it (block-contract §2). ActionSheet lists COMMANDS, each a
// Button that runs and is gone, with no state; this lists VALUES, one of which is stored and shown
// back on the trigger. That is the Menu-versus-ListBox line component-usage.md draws, and a mode
// would swap ActionSheet's Buttons for a ListBox under the same name, two meanings behind one prop.
//
// Drawer owns the overlay, ListBox the single selection, its keyboard and the row look (React
// Aria); this Block only closes the sheet after a pick and keeps an uncontrolled record, which is
// plain React state.
import { useId, useState } from "react";
import type { Key, ReactNode } from "react";
import { Button } from "../components/Button";
import { DrawerContent, DrawerFooter, DrawerHeader, DrawerTitle, DrawerTrigger } from "../components/Drawer";
import { ListBox, ListBoxItem } from "../components/ListBox";
import { Text } from "../components/Text";
import { Stack } from "../layouts/Stack";
import "./OptionSheet.css";

export interface OptionSheetOption {
  /** Stable key, passed to `onChange`. */
  id: string;
  /** The option as read, e.g. "Lowest price". */
  label: string;
}

export interface OptionSheetGroup {
  /** Stable key, and the key of this group's pick in the value record. */
  id: string;
  /** The group's name, shown over its options, e.g. "상품 정렬". */
  label: string;
  /** The group's options, in the order they show. */
  options: OptionSheetOption[];
}

export interface OptionSheetBaseProps {
  /** Control that opens the sheet. It should show the current option's label. */
  trigger: ReactNode;
  /** Sheet heading. **Required**: it names the sheet and the list (WCAG 4.1.2). */
  title: string;
  /** Accessible name of the close (X) button, for a screen that is not in English.
      @default "Close" */
  closeLabel?: string;
  /** How the sheet attaches to the viewport, forwarded to DrawerContent: `inset` is a floating
   *  card, `full-bleed` a bottom sheet that touches the screen's edges. A product picks one for every
   *  sheet it shows.
   * @default "inset"
   */
  variant?: "inset" | "full-bleed";
}

/** One list: one option is picked, and the pick applies and closes the sheet. */
export interface OptionSheetListProps extends OptionSheetBaseProps {
  /** The options, in the order they show. */
  options: OptionSheetOption[];
  groups?: never;
  /** The picked option's id. */
  value: string;
  defaultValue?: never;
  /** Called with the picked option's id. The sheet then closes. */
  onChange: (id: string) => void;
  onApply?: never;
  applyLabel?: never;
}

/** Labelled groups: one option is picked PER GROUP, so the value is a record keyed by group id. */
export interface OptionSheetGroupsProps extends OptionSheetBaseProps {
  options?: never;
  /** The options in labelled groups, in the order they show. Each group is its own list with its
   *  own pick, so option ids need only be unique within their group. */
  groups: OptionSheetGroup[];
  /** The picked option's id per group, keyed by group id. Omit it for an uncontrolled sheet. */
  value?: Record<string, string>;
  /** The picks an uncontrolled sheet starts with, keyed by group id. */
  defaultValue?: Record<string, string>;
  /** Called with the whole record whenever a pick changes. Without `onApply` the sheet then closes;
   *  with it the sheet stays open and the pick is pending. A consumer that must drop unapplied picks
   *  when the sheet is dismissed holds them as a draft here and commits them in `onApply`. */
  onChange?: (value: Record<string, string>) => void;
  /** Ends the sheet in an apply action that confirms the picks of every group together. Called with
   *  the record as it stands; the sheet then closes. */
  onApply?: (value: Record<string, string>) => void;
  /** The apply action's label. Used only with `onApply`.
   * @default "Apply"
   */
  applyLabel?: string;
}

export type OptionSheetProps = OptionSheetListProps | OptionSheetGroupsProps;

const renderOption = (option: OptionSheetOption) => (
  <ListBoxItem key={option.id} id={option.id}>
    {option.label}
  </ListBoxItem>
);

export function OptionSheet(props: OptionSheetProps) {
  const { trigger, title, closeLabel, variant } = props;
  const [isOpen, setOpen] = useState(false);
  const groupId = useId();
  // The uncontrolled record, read only when `groups` is given without `value`.
  const [ownRecord, setOwnRecord] = useState<Record<string, string>>(
    (props.groups && props.defaultValue) || {},
  );

  let body: ReactNode;
  let footer: ReactNode;
  if (props.groups) {
    const { groups, onChange, onApply, applyLabel = "Apply" } = props;
    const record = props.value ?? ownRecord;
    body = (
      <Stack gap="medium">
        {groups.map((group) => (
          // One group: its name over its own single-selection list, which the name labels.
          <Stack key={group.id} gap="2x-small">
            <Text id={`${groupId}-${group.id}`} variant="label" size="small" tone="muted" elementType="h3">
              {group.label}
            </Text>
            {/* spacing: attachment — the group's name heads its list */}
            <ListBox
              aria-labelledby={`${groupId}-${group.id}`}
              variant="grouped"
              indicator="check"
              selectionMode="single"
              selectedKeys={record[group.id] == null ? [] : [record[group.id]]}
              onSelectionChange={(keys) => {
                // A press on the picked row reports an empty selection: the pick stays (one per
                // group, always), and without an apply action the press still closes the sheet.
                const [key] = keys as Set<Key>;
                if (key != null && key !== record[group.id]) {
                  const next = { ...record, [group.id]: String(key) };
                  setOwnRecord(next);
                  onChange?.(next);
                }
                if (!onApply) setOpen(false);
              }}
            >
              {group.options.map(renderOption)}
            </ListBox>
          </Stack>
        ))}
      </Stack>
    );
    footer = onApply && (
      // One action, so it spans the sheet (`stack`) rather than hugging the end of the row.
      <DrawerFooter layout="stack">
        {/* usage: completing-action — confirms every group's pick and closes the sheet */}
        <Button size="large" variant="primary" slot="close" onPress={() => onApply(record)}>
          {applyLabel}
        </Button>
      </DrawerFooter>
    );
  } else {
    const { options, value, onChange } = props;
    body = (
      <ListBox
        aria-label={title}
        variant="grouped"
        indicator="check"
        selectionMode="single"
        selectedKeys={[value]}
        // Pressing the picked row again deselects it in React Aria's single mode, which still
        // reports a change: an empty one. The value stays (it is controlled) and the sheet closes,
        // so every press is "apply and close", the picked row included.
        onSelectionChange={(keys) => {
          const [key] = keys as Set<Key>;
          if (key != null) onChange(String(key));
          setOpen(false);
        }}
      >
        {options.map(renderOption)}
      </ListBox>
    );
  }

  return (
    <DrawerTrigger isOpen={isOpen} onOpenChange={setOpen}>
      {trigger}
      <DrawerContent
        variant={variant}
        side="sheet"
        className="sd-optionsheet"
        closeLabel={closeLabel}
        header={
          <DrawerHeader>
            <DrawerTitle>{title}</DrawerTitle>
          </DrawerHeader>
        }
        footer={footer}
      >
        {body}
      </DrawerContent>
    </DrawerTrigger>
  );
}
